"""Append explanatory, data-backed analysis cells to the four project notebooks."""
from pathlib import Path
import nbformat

ROOT = Path(__file__).resolve().parents[1]

def add(notebook, markdown, code):
    nb = nbformat.read(ROOT / "notebooks" / notebook, as_version=4)
    nb.cells.extend([nbformat.v4.new_markdown_cell(markdown), nbformat.v4.new_code_cell(code)])
    nbformat.write(nb, ROOT / "notebooks" / notebook)

add("01_data_collection_and_eda.ipynb", "## Data quality and timestamp inspection\n\nThis section checks the sampling timeline, repeated timestamps, target range, and missingness percentages. Gaps are reported rather than silently filled.", "import pandas as pd\ndf['date']=pd.to_datetime(df.date)\nquality=pd.DataFrame({'dtype':df.dtypes.astype(str),'missing':df.isna().sum(),'missing_pct':100*df.isna().mean(),'n_unique':df.nunique()})\nquality\n")
add("01_data_collection_and_eda.ipynb", "### Sampling intervals\n\nThe target is the next *observed* row. Checking intervals makes any departures from ten minutes visible before interpreting the forecasting horizon.", "intervals=df.date.sort_values().diff().dropna().dt.total_seconds().div(60)\nintervals.describe(), intervals.value_counts().head(10), (intervals!=10).sum()\n")
add("01_data_collection_and_eda.ipynb", "### Target distribution and high-use observations\n\nThe quantiles describe the skew and tail. High observations are retained because they may reflect real appliance use; this plot alone does not label them as errors or waste.", "df.Appliances.quantile([0,.25,.5,.75,.9,.95,.99,1]), df.nlargest(10,'Appliances')[['date','Appliances','lights']]\n")
add("01_data_collection_and_eda.ipynb", "### Daily and weekly patterns\n\nHourly and weekday averages summarize recurring patterns. These group averages are descriptive and may be affected by the short, single-home collection period.", "df['hour']=df.date.dt.hour + df.date.dt.minute/60\ndf['weekday']=df.date.dt.day_name()\nfig,ax=plt.subplots(1,2,figsize=(13,4))\ndf.groupby('hour').Appliances.mean().plot(ax=ax[0]); ax[0].set(title='Mean appliance use by hour',xlabel='Hour of day',ylabel='Wh per 10 min')\ndf.groupby('weekday').Appliances.mean().reindex(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']).plot(kind='bar',ax=ax[1]); ax[1].set(title='Mean appliance use by weekday',xlabel='Day',ylabel='Wh per 10 min'); plt.tight_layout()\n")
add("01_data_collection_and_eda.ipynb", "### Temperature and humidity associations\n\nScatter plots show association with representative indoor and outdoor sensors. Density and overlapping observations can obscure structure; these are not causal effects.", "fig,ax=plt.subplots(1,2,figsize=(12,4))\nsns.scatterplot(data=df.sample(min(2500,len(df)),random_state=42),x='T_out',y='Appliances',alpha=.3,s=15,ax=ax[0]); ax[0].set(title='Outdoor temperature and appliance use',xlabel='Outdoor temperature (°C)',ylabel='Wh per 10 min')\nsns.scatterplot(data=df.sample(min(2500,len(df)),random_state=42),x='RH_1',y='Appliances',alpha=.3,s=15,ax=ax[1]); ax[1].set(title='Indoor humidity and appliance use',xlabel='RH_1 (%)',ylabel='Wh per 10 min'); plt.tight_layout()\n")
add("01_data_collection_and_eda.ipynb", "### Lighting and random variables\n\nThe source includes lighting energy and two random variables. Compare the latter directly and examine whether they carry distinct information before treating them as meaningful predictors.", "fig,ax=plt.subplots(1,2,figsize=(12,4))\nsns.scatterplot(data=df.sample(min(2500,len(df)),random_state=42),x='lights',y='Appliances',alpha=.3,s=15,ax=ax[0]); ax[0].set(title='Lighting and appliance use',xlabel='Lighting (Wh per 10 min)',ylabel='Appliances (Wh per 10 min)')\nsns.scatterplot(data=df.sample(min(2500,len(df)),random_state=42),x='rv1',y='rv2',alpha=.3,s=12,ax=ax[1]); ax[1].set(title='Source random variables rv1 and rv2',xlabel='rv1',ylabel='rv2'); plt.tight_layout()\ndf[['rv1','rv2']].corr()\n")
add("01_data_collection_and_eda.ipynb", "### Correlation and collinearity review\n\nThe largest absolute correlations can signal redundant predictors. They are useful for understanding model inputs, but they do not prove that a sensor causes a change in appliance use.", "corr=df.select_dtypes('number').corr()\ntarget_corr=corr.Appliances.drop('Appliances').sort_values(key=abs,ascending=False)\ntarget_corr.head(15)\n")
add("01_data_collection_and_eda.ipynb", "## EDA conclusions\n\nSummarize the actual observations above: target skew and range, any timestamp gaps, time-of-day pattern, and the strongest descriptive associations. State explicitly that this is a single-home observational dataset and that correlation does not establish cause.", "print(f'Rows: {len(df):,}; columns: {df.shape[1]}; missing cells: {int(df.isna().sum().sum())}; duplicate timestamps: {int(df.date.duplicated().sum())}')\nprint('Median interval (minutes):', intervals.median(), '| non-10-minute intervals:', int((intervals!=10).sum()))\nprint('Largest absolute target correlations:')\ndisplay(target_corr.head(8).to_frame('correlation'))\n")

add("02_preprocessing_and_feature_engineering.ipynb", "## Cleaning report and decisions\n\nInspect counts before and after cleaning. Duplicate timestamps keep the last reading; numeric gaps use forward then backward fill. In the downloaded source there are no missing cells, so imputation does not change this dataset. Extremes remain in place.", "report, clean.shape\n")
add("02_preprocessing_and_feature_engineering.ipynb", "## Target alignment example\n\nFor each row *t*, the target is the next observed Appliances value. The feature matrix contains current Appliance consumption and historical lags. The displayed rows make the time alignment concrete.", "alignment=clean[['date','Appliances']].copy()\nalignment['target_next']=alignment.Appliances.shift(-1)\nalignment['next_timestamp']=alignment.date.shift(-1)\nalignment[['date','Appliances','next_timestamp','target_next']].head(8)\n")
add("02_preprocessing_and_feature_engineering.ipynb", "## Feature definitions and availability\n\nEvery predictor must be available at the forecast origin. Rolling features shift the consumption series before aggregation, preventing the value being predicted from entering its own history summary.", "feature_notes={'appliances_current':'Appliances observed at t, Wh/10 min','appliances_lag_k':'Appliances k observations before t','appliances_roll_mean_w':'mean of the preceding w readings, excludes t','appliances_roll_std_w':'standard deviation of the preceding w readings, excludes t','hour_sin/hour_cos':'cyclic encoding of current hour','day_of_week/is_weekend':'calendar fields at t','target_next':'Appliances at next observed row; target only'}\npd.Series(feature_notes,name='definition').to_frame()\n")
add("02_preprocessing_and_feature_engineering.ipynb", "## Leakage checks\n\nConfirm that the last engineered feature row corresponds to a timestamp before the final raw row, that next-target values are shifted, and that each split occupies a later time block. The model's learned transformations are fit only on training rows.", "assert (t.reset_index(drop=True) < clean.date.iloc[-1]).all()\nassert X.index.is_monotonic_increasing\nassert parts['train'][2].max() < parts['validation'][2].min() < parts['test'][2].min()\n{'first_feature_time':str(t.iloc[0]),'last_feature_time':str(t.iloc[-1]),'last_raw_time':str(clean.date.iloc[-1]),'chronological_order':True}\n")
add("02_preprocessing_and_feature_engineering.ipynb", "## Feature-group ablation\n\nThe experiment fits on the training block and compares validation MAE/RMSE/R². Mutual information ranks are calculated from training only. The test period is not used in this comparison.", "from pathlib import Path\nimport pandas as pd\nabl=Path('reports/metrics/feature_ablation.csv')\npd.read_csv(abl) if abl.exists() else 'Run python -m wattwise.train to generate this train/validation ablation.'\n")
add("02_preprocessing_and_feature_engineering.ipynb", "## Preprocessing conclusion\n\nDescribe how many rows were removed by warm-up and next-target alignment, the final feature count, and whether selected history features improve validation performance. Explain that the chronological holdout remains isolated from these choices.", "print('Usable rows:',len(X),'features:',X.shape[1])\nprint('Split sizes:',{k:len(v[0]) for k,v in parts.items()})\n")

add("03_advanced_modeling_and_optimization.ipynb", "## Baseline and advanced model table\n\nAll individual estimators below use the same training and validation periods. Persistence uses Appliances at time *t* to predict the next interval.", "score_table=pd.DataFrame([{'model':k,**v} for k,v in scores.items()]).sort_values('MAE')\nscore_table\n")
add("03_advanced_modeling_and_optimization.ipynb", "### Compare validation errors\n\nMAE is easy to interpret in Wh per 10-minute interval. RMSE gives greater weight to large misses. R² may be negative if a model is worse than predicting the validation mean.", "fig,ax=plt.subplots(figsize=(10,4)); score_table.plot.bar(x='model',y='MAE',legend=False,ax=ax,color='#2a9d8f'); ax.set(title='Validation MAE by model',xlabel='Model',ylabel='MAE (Wh / 10 min)'); plt.xticks(rotation=35,ha='right'); plt.tight_layout()\n")
add("03_advanced_modeling_and_optimization.ipynb", "## Expanding-window validation\n\nThe time-series CV folds preserve order: each validation fold comes after its training fold. This small Ridge example illustrates the evaluation design used for tuning; the final test is not involved.", "from sklearn.model_selection import TimeSeriesSplit\nfrom sklearn.base import clone\ncv_rows=[]\nfor fold,(a,b) in enumerate(TimeSeriesSplit(n_splits=4).split(Xtr),1):\n    cv_model=clone(model_factory()['Ridge']).fit(Xtr.iloc[a],ytr.iloc[a])\n    cv_rows.append({'fold':fold,'train_end':int(a[-1]),'validation_start':int(b[0]),**regression_metrics(ytr.iloc[b],cv_model.predict(Xtr.iloc[b]))})\npd.DataFrame(cv_rows)\n")
add("03_advanced_modeling_and_optimization.ipynb", "## Hyperparameter search results\n\nOptuna optimizes expanding-fold MAE on training history. The validation score shown below is a separate model check. Trials and parameters are recorded; no test values influence tuning.", "search\n")
add("03_advanced_modeling_and_optimization.ipynb", "## Ensemble and feature ablation evidence\n\nThe training command builds validation voting and a walk-forward stack where each meta-training prediction comes from a base model trained on earlier rows. Feature ablation compares all features, no lag/rolling consumption history, and training-only mutual-information top 20.", "from pathlib import Path\nimport pandas as pd\ncomparison=Path('reports/model_comparison.csv')\nprint('Saved model comparison:'); display(pd.read_csv(comparison) if comparison.exists() else 'Run training first.')\nprint('Train/validation feature ablation:'); display(pd.read_csv('reports/metrics/feature_ablation.csv') if Path('reports/metrics/feature_ablation.csv').exists() else 'Run training first.')\n")
add("03_advanced_modeling_and_optimization.ipynb", "## Final held-out test results\n\nOnly after validation selection is complete is the selected model scored on the final period. Read saved artifacts to report actual run outputs; do not use these numbers to revise model selection.", "from pathlib import Path\nimport json\nmetric_path=Path('reports/metrics/final_metrics.json')\njson.loads(metric_path.read_text()) if metric_path.exists() else 'Run python -m wattwise.train to create the final test evaluation.'\n")
add("03_advanced_modeling_and_optimization.ipynb", "## Modeling conclusions\n\nIdentify the validation-selected model, compare it to persistence, and discuss any validation-to-test performance change. Include runtime/dependency considerations and the risk of overfitting a single-house period.", "print('Validation best MAE:',score_table.iloc[0][['model','MAE']].to_dict())\n")

add("04_anomaly_detection_and_explainability.ipynb", "## Residual behavior over time\n\nResiduals are observed minus expected. Positive values mean actual consumption exceeded the forecast; negative values mean it was lower. The cutoff was calibrated using validation residuals only.", "residual=yte.to_numpy()-pt\nfig,ax=plt.subplots(2,1,figsize=(13,7),sharex=True)\nax[0].plot(s['test'][2],yte,label='Observed',lw=.7); ax[0].plot(s['test'][2],pt,label='Forecast',lw=.7); ax[0].set(ylabel='Wh / 10 min',title='Held-out actual and forecast'); ax[0].legend()\nax[1].plot(s['test'][2],residual,lw=.6); ax[1].axhline(cutoff,color='red',ls='--'); ax[1].axhline(-cutoff,color='red',ls='--'); ax[1].set(xlabel='Timestamp',ylabel='Residual (Wh)',title='Forecast residual over test period'); plt.tight_layout()\n")
add("04_anomaly_detection_and_explainability.ipynb", "## Residual distribution and candidate events\n\nThe empirical cutoff marks unusual error magnitudes relative to validation. This threshold produces candidates, not verified anomalies or waste labels.", "flags=residual_flags(yte,pt,cutoff)\nfig,ax=plt.subplots(figsize=(9,4)); ax.hist(residual,bins=50,color='#457b9d'); ax.axvline(cutoff,color='red',ls='--',label='± validation cutoff'); ax.axvline(-cutoff,color='red',ls='--'); ax.set(title='Held-out residual distribution',xlabel='Observed − predicted (Wh)',ylabel='Count'); ax.legend(); plt.tight_layout()\n{'cutoff_wh':cutoff,'candidate_count':int(flags['flag'].sum()),'high_consumption_candidates':int(flags['high_consumption'].sum())}\n")
add("04_anomaly_detection_and_explainability.ipynb", "## Isolation Forest scores\n\nIsolation Forest is fitted only on training feature vectors. Its score is a relative outlier ranking, not an anomaly probability. The 99th percentile of training outlier scores is used here for a transparent demonstration.", "iso=fit_isolation_forest(Xtr,seed=42)\niso_train=-iso.score_samples(Xtr); iso_test=-iso.score_samples(Xte); iso_cut=float(__import__('numpy').quantile(iso_train,.99))\n{'training_score_cutoff':iso_cut,'test_candidates':int((iso_test>iso_cut).sum())}\n")
add("04_anomaly_detection_and_explainability.ipynb", "## Compare synthetic detector recovery\n\nGround truth exists only for injected spikes in a separate copy of the test target. Natural test observations remain unlabeled. Precision/recall can be low when a fixed high residual threshold is compared with this chosen injection strength.", "syn_iso_X=Xte.copy(); syn_iso_X['appliances_current']=synthetic\nsyn_iso_score=-iso.score_samples(syn_iso_X)\nsyn_iso_flags=syn_iso_score>iso_cut\n{'residual_detector':synthetic_metrics(labels,scores),'isolation_forest_detector':synthetic_metrics(labels,syn_iso_flags),'injected_indices_count':len(indices)}\n")
add("04_anomaly_detection_and_explainability.ipynb", "## Local explanation with SHAP\n\nThe optional permutation SHAP explanation shows how input features shift one forecast relative to a background sample. If SHAP cannot run with the installed model/library combination, use the trained global importance and state the fallback. Attributions explain model behavior, not causes.", "from wattwise.explainability import local_shap_values\nlocal,shap_error=local_shap_values(model.predict,Xtr.sample(min(500,len(Xtr)),random_state=42),Xte.iloc[[0]])\nif shap_error: print(shap_error)\nelse: display(local.head(15))\n")
add("04_anomaly_detection_and_explainability.ipynb", "## Interpretation and limitations\n\nSeparate four statements: (1) a statistical residual crossed a cutoff; (2) observed use was higher than expected; (3) the event may merit waste investigation; (4) waste is confirmed. This dataset supports only the first two. Confirmation needs labels, context, or an intervention measurement.", "print('Unlabeled real test rows:',len(yte),'| synthetic injected rows:',int(labels.sum()))\nprint('No supervised accuracy is reported for naturally occurring anomalies.')\n")

print("Expanded all four notebooks with additional explanatory and analysis cells.")
